import type { BoardCategory, SeasonId } from "./config";

export interface Listing {
  /** Stable key: hostname (no www) or host/first-path-segment for shared hosts. */
  domain: string;
  name: string;
  /** Normalised destination URL (tracking parameters stripped). */
  url: string;
  category: BoardCategory;
  tagline: string;
  /** Epoch ms. Older listing wins ties. */
  createdAt: number;
  /** True once the owner proved control of the domain. */
  verified: boolean;
  /** True for sample listings generated by the demo adapter. */
  sample?: boolean;
}

export interface Bid {
  id: string;
  domain: string;
  amountCents: number;
  /** Epoch ms. */
  at: number;
  sample?: boolean;
}

export interface BoardRow {
  rank: number;
  /** Rank one hour ago, or null if the listing was not on the board then. */
  prevRank: number | null;
  listing: Listing;
  totalCents: number;
  clicks: number;
  /** Cost for this listing to pass the listing directly above it. null for #1. */
  climbCostCents: number | null;
}

export interface SeasonWindow {
  start: number;
  /** null = open ended (all time). */
  end: number | null;
}

export interface BoardSnapshot {
  season: SeasonId;
  window: SeasonWindow;
  category: BoardCategory | null;
  rows: BoardRow[];
  stats: { listings: number; totalCents: number; clicks: number };
  /** Amount a brand-new listing must pay to take #1 right now. */
  leadCostCents: number;
  generatedAt: number;
  mode: "demo" | "live";
}

export interface RankPoint {
  at: number;
  rank: number | null;
}

export interface ListingDetail {
  listing: Listing;
  ranks: Record<SeasonId, { rank: number | null; totalCents: number; of: number }>;
  /** Public bid ledger, newest first. */
  ledger: Bid[];
  /** All-time rank over time, oldest first. */
  history: RankPoint[];
  clicks: number;
  /** Cost to take #1 in each season. */
  leadCostCents: Record<SeasonId, number>;
}

export interface NewListingInput {
  url: string;
  name: string;
  tagline: string;
  category: BoardCategory;
}

export interface QuoteInput {
  /** Either an existing listing key or a new listing (url is enough to compute the key). */
  domain?: string;
  url?: string;
  amountCents: number;
  season: SeasonId;
}

export type Quote =
  | {
      ok: true;
      domain: string;
      isNewListing: boolean;
      amountCents: number;
      currentTotalCents: number;
      newTotalCents: number;
      currentRank: number | null;
      newRank: number;
      of: number;
      /** Minimum extra amount to take #1 in this season. */
      costToLeadCents: number;
      /** Minimum extra amount to move up one place (null if already #1). */
      costToClimbCents: number | null;
    }
  | { ok: false; error: string };

export interface BidRequest {
  /** Existing listing key, or a new listing to create with this bid. */
  domain?: string;
  newListing?: NewListingInput;
  amountCents: number;
  acceptedTerms: boolean;
}

/**
 * ok + bid/listing: the bid is recorded (demo, or a live backend that captured payment synchronously).
 * ok + checkoutUrl only: redirect the buyer to the hosted payment page. The bid is recorded later by a payment webhook.
 */
export type BidResult =
  | { ok: true; bid: Bid; listing: Listing; checkoutUrl?: undefined }
  | { ok: true; checkoutUrl: string; bid?: undefined; listing?: undefined }
  | { ok: false; error: string };

export interface VerificationInfo {
  verified: boolean;
  token: string;
  methods: { type: "dns" | "meta" | "file"; instruction: string; value: string }[];
}

/** Click counts per listing key (all time). */
export type ClickCounts = Record<string, number>;

export interface ActivityItem {
  id: string;
  domain: string;
  name: string;
  amountCents: number;
  /** Epoch ms. */
  at: number;
  /** True when this bid made the listing the all-time #1. */
  tookLead: boolean;
  sample?: boolean;
}

export interface HallOfFameEntry {
  season: "daily" | "weekly" | "monthly";
  /** "Yesterday", "Last week", "Last month". */
  label: string;
  /** The closed season window. */
  window: { start: number; end: number };
  /** null when nobody paid in that season. */
  winner: { listing: Listing; totalCents: number } | null;
  /** Listings that had a total in that season. */
  entrants: number;
}

export type HallOfFame = HallOfFameEntry[];

export type OkOrError = { ok: true } | { ok: false; error: string };

export interface VerificationCheck {
  verified: boolean;
  /** Plain-language outcome to show the owner. */
  message: string;
  /** True when this result came from the demo simulation, not a real DNS or page check. */
  simulated?: boolean;
}

/** The interface every adapter (demo, live HTTP) implements. */
export interface BoardAdapter {
  getBoard(season: SeasonId, category: BoardCategory | null): Promise<BoardSnapshot>;
  /** null when the listing does not exist. */
  getListing(domain: string): Promise<ListingDetail | null>;
  quote(input: QuoteInput): Promise<Quote>;
  /** idempotencyKey: reuse the same key when retrying the same purchase so it can never be charged twice. */
  purchaseBid(req: BidRequest, idempotencyKey?: string): Promise<BidResult>;
  recordClick(domain: string): Promise<void>;
  getHallOfFame(): Promise<HallOfFame>;
  getActivity(limit: number): Promise<ActivityItem[]>;
  getVerification(domain: string): Promise<VerificationInfo>;
  checkVerification(domain: string): Promise<VerificationCheck>;
  reportListing(domain: string, reason: string): Promise<OkOrError>;
  subscribeAlerts(domain: string, email: string): Promise<OkOrError>;
  /** Call cb whenever data may have changed. Returns an unsubscribe function. */
  subscribe(cb: () => void): () => void;
}

/** What the UI uses: the adapter plus browser-local "my listings". */
export interface BoardApi extends BoardAdapter {
  /** Listing keys this browser created or paid for, newest first. */
  getMine(): Promise<string[]>;
  getMyListings(): Promise<ListingDetail[]>;
}
